class Solution {
    public int leastInterval(char[] tasks, int n) {
        int[] counts = new int[26];
        for (char t : tasks) counts[t - 'A']++;
        int maxCount = 0, maxFreqTasks = 0;
        for (int c : counts) {
            if (c > maxCount) { maxCount = c; maxFreqTasks = 1; }
            else if (c == maxCount) maxFreqTasks++;
        }
        int frame = (maxCount - 1) * (n + 1) + maxFreqTasks;
        return Math.max(tasks.length, frame);
    }
}
